package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.*;import com.eventpulse.config.DynamoDbConfig;import com.eventpulse.repository.*;import com.eventpulse.service.*;import java.util.Map;
public class ReminderHandler implements RequestHandler<Map<String,Object>,String>{private final ReminderService reminders;public ReminderHandler(){var db=DynamoDbConfig.enhancedClient();var er=new EventRepository(db,DynamoDbConfig.table("EVENTS_TABLE","EventPulse-Events"));var rr=new RegistrationRepository(db,DynamoDbConfig.table("REGISTRATIONS_TABLE","EventPulse-Registrations"));var ur=new UserRepository(db,DynamoDbConfig.table("USERS_TABLE","EventPulse-Users"));var events=new EventService(er);var notifications=new NotificationService(com.eventpulse.config.SesConfig.client(),com.eventpulse.config.SesConfig.sender(),System.getenv("SES_CONFIGURATION_SET"),new NotificationRepository(db,DynamoDbConfig.table("NOTIFICATIONS_TABLE","EventPulse-Notifications")),rr,ur);reminders=new ReminderService(events,notifications);}public ReminderHandler(ReminderService r){reminders=r;}public String handleRequest(Map<String,Object> input,Context context){if(input==null||input.get("eventId")==null||input.get("reminderType")==null)throw new IllegalArgumentException("eventId and reminderType are required");int accepted=reminders.sendReminder(input.get("eventId").toString(),input.get("reminderType").toString());return "Accepted by SES for "+accepted+" recipients";}}
